import{Tt as e,at as t,rt as n,t as r}from"./chunks/framework.j55wycBY.js";var i=JSON.parse(`{"title":"The Docs Build Waiting on Git","description":"","frontmatter":{"authorship":["ai"]},"headers":[],"relativePath":"developer/story/docs-build-git-history.md","filePath":"developer/story/docs-build-git-history.md"}`),a={name:`developer/story/docs-build-git-history.md`};function o(r,i,a,o,s,c){return e(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795875178000`},[...i[0]||=[t(`<h1 id="the-docs-build-waiting-on-git" tabindex="-1">The Docs Build Waiting on Git <a class="header-anchor" href="#the-docs-build-waiting-on-git" aria-label="Permalink to “The Docs Build Waiting on Git”">​</a></h1><p><em>Why a fast local build took minutes in CI.</em></p><p>Written with AI, November 2026.</p><p>The Docs job took almost seven minutes, though publishing itself took six seconds. A later diagnostic run took nearly fourteen minutes. The diagram cache restored successfully, and Kroki was healthy; neither explained the delay.</p><p>We streamed the Nx task output to locate the pause. VitePress spent over ten minutes before its first Vite build hook, while page rendering and Pagefind indexing each took seconds or less. The same uncached docs build took under ten seconds locally.</p><p>The culprit was the interaction between two choices:</p><ul><li>The Docs checkout used <code>fetch-depth: 0</code> and <code>filter: tree:0</code>: it had full commit history, but omitted historical Git trees.</li><li><code>vitepress-plugin-pagefind</code> scans Markdown Git history during configuration to provide search-result date metadata, even when the dates are not displayed.</li></ul><p>Walking that history caused Git to fetch missing trees on demand. In a controlled local clone, the same history scan with <code>tree:0</code> made 2,922 fetches and timed out after 90 seconds. With <code>blob:none</code>, it finished in 0.18 seconds and returned the same history as the full clone.</p><p>We changed only the Docs checkout to <code>blob:none</code>. It retains commits and historical trees but omits historical file contents until needed. In the <a href="https://github.com/notopia-uit/notopia/actions/runs/46140110306" target="_blank" rel="noreferrer">verification run</a>, VitePress built in 7.06 seconds and the Docs job completed in 2 minutes 45 seconds; the diagram cache still hit. Most remaining time was setup and pulling the Kroki container.</p><p>Future docs builds should avoid the repeated tree fetches while retaining history for Pagefind. The Main job still uses <code>tree:0</code>; if another tool there starts walking file history, it may encounter the same tradeoff.</p>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};